validator:
function validate(input) {
  const [{ Person = [] }] = input;
  const ids = new Set();
  for (const [id, email] of Person) {
    if (id === null) return 'Every row needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Person.`;
    ids.add(id);
    if (email === null) return 'email must not be null.';
    if (email !== email.toLowerCase()) return `email ${email} has uppercase letters.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const Person = [];
  if (size === 'small') {
    const pool = ['a@b.com', 'c@d.com', 'john@x.org', 'bob@mail.net', 'kim@y.io'];
    const rows = Math.floor(rand() * 9);
    for (let id = 1; id <= rows; id++) Person.push([id, pool[Math.floor(rand() * pool.length)]]);
  } else {
    // 2,000 rows over about 1,400 addresses: many appear once, some twice or more.
    for (let id = 1; id <= 2000; id++) Person.push([id * 3, `user${Math.floor(rand() * 1400)}@site${Math.floor(rand() * 2)}.com`]);
  }
  return [{ Person }];
}
